scwin.gUIsurCd; // update시 팝업에 넘겨주기 위해  필요
scwin.gSelctBasYy; // update시 팝업에 넘겨주기 위해  필요
scwin.gComAbbrv; // update시 팝업에 넘겨주기 위해  필요
scwin.gExcnt; // update시 팝업에 넘겨주기 위해  필요

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gBelngDepCd = js_belngdepcd;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name getProvider
 * @description 20250509 밸류업팀에서 '밸류업 우수기업'  유형 추가 요청 '밸류업 우수기업'지정은 밸류업팀에서만, 다른팀에서 지정 불가 20250523 유가, 코스닥 공시팀에서 밸류업우수기업목록도 조회함 선정유형 코드 생성시 유가는 1X,코스닥2X, 밸류업9X 로 만들것
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    const arr = url.split("?");
    // alert(url +"     =      "+ arr);
    return (arr.length > 1 ? arr[1] : '');
};

/**
 * @method
 * @name setCode
 * @description 페이지 로딩 시 필요한 변수 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    // 시장구분 셋팅
    scwin.gLdMktTp = js_market;
    panel_mkt.hide();
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
    } else {
        pnl_team.hide();
        rdo_MKT_ID.setValue('9');
        if (scwin.gBelngDepCd === "1I00" || scwin.gDepCd === "1I00") {
            // 밸류업지원부

        } else {
            panel_mkt.show("");
        }
    }
    scwin.gLdMktTp = rdo_MKT_ID.getValue();
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 선정유형
    const sbmOptions3 = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    pnl_1.hide(); // 표창유형

    if (scwin.getProvider() === 'POPUPMODE') {
        // 회사코드 셋팅
        txb_isur_cd.setValue(scwin.gIsurCd);
        txb_com_abbrv.setValue(scwin.gCOM_NM);
    }

    // 달력
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear() + 1, 10); // 다음년도
    const mm = parseInt(ToDay.getMonth(), 10) + 1;
    let str = " ";
    for (let i = yyyy; i >= 2005; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);

    // 시상년도 시작일
    cmb_AW_YYYY.CBData = str;
    // 시상년도 종료일
    cmb_AW_YYYY_END.CBData = str;
    cmb_AW_YYYY.setSelectedIndex(0);
    txt_SelectBasYy.style.visibility = "hidden";
    cmb_AW_YYYY.setValue(parseInt(ToDay.getYear() - 2, 10));
    cmb_AW_YYYY_END.setValue(parseInt(ToDay.getYear(), 10));

    // 시상년도 검색 시작년도 enable 처리
    // cmb_AW_YYYY.Enable = false;

    // 시장구분에 따른 유형설정
    // 선정유형 코드 생성시 유가는 1X,코스닥2X, 밸류업9X 로 만들것
    if (scwin.gLdMktTp === "1") {
        // 유가_선정유형
        label_10.setValue("선정유형");
        str = "^전체,11^공시우수법인,12^우수위원,13^공시우수법인(코스닥),99^밸류업 우수기업";
        $c.cm.setColumnProp(grd_Grid, 'EXCNT_DISCLS_CORP_TP_NM', 'Name', '선정 유형');
        $c.cm.setColumnProp(grd_Grid, 'VLUP_AWARD_TP_NM', 'show', 'true'); // 밸류업수상구분코드
        $c.cm.setColumnProp(grd_Grid, 'VLUP_EXCNT_CORP_ORD', 'show', 'false'); // 밸류업우수법인순서

    } else if (scwin.gLdMktTp === "2") {
        // 코스닥_유형
        label_10.setValue("유형");
        str = "^전체,21^장기성실공시우수,22^실적예측공시우수,23^IR활동우수,24^종합평가우수,25^우수위원,99^밸류업 우수기업";
        $c.cm.setColumnProp(grd_Grid, 'EXCNT_DISCLS_CORP_TP_NM', 'Name', "유형");
        $c.cm.setColumnProp(grd_Grid, 'VLUP_AWARD_TP_NM', 'show', 'true'); // 밸류업수상구분코드
        $c.cm.setColumnProp(grd_Grid, 'VLUP_EXCNT_CORP_ORD', 'show', 'false'); // 밸류업우수법인순서

    } else {
        pnl_1.show("");
        cmb_DEP_CD.setDisabled(true);
        $c.cm.setColumnProp(grd_Grid, 'EXCNT_DISCLS_CORP_TP_NM', 'Name', "유형");
        $c.cm.setColumnProp(grd_Grid, 'VLUP_AWARD_TP_NM', 'show', 'true'); // 밸류업수상구분코드
        $c.cm.setColumnProp(grd_Grid, 'VLUP_EXCNT_CORP_ORD', 'show', 'true'); // 밸류업우수법인순서

        if (scwin.gBelngDepCd === "1I00" || scwin.gDepCd === "1I00") {
            // 밸류업지원부
            str = "99^밸류업 우수기업";
        } else {
            str = "^전체,99^밸류업 우수기업,21^(코)장기성실공시우수,22^(코)실적예측공시우수,23^(코)IR활동우수,24^(코)종합평가우수,25^(코)우수위원,11^(유)공시우수법인,12^(유)우수위원,13^(유)공시우수법인(코스닥)";
        }
    }
    cmb_Excnt.CBData = str;
    cmb_Excnt.setSelectedIndex(0);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !정보--;
셋팅-- > function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd; // 법인코드
    scwin.gCOM_NM = $c.frame.path("../").scwin.gComAbbrv; // 회사명
    scwin.gSchDate = $c.frame.path("../").gDtecDate; // 조회일자
    scwin.gExcnt = $c.frame.path("../").scwin.gExcnt; // 유형

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let vISUR_CD = txb_isur_cd.getValue();
    let vAW_SCH_DD = cmb_AW_YYYY.getValue();
    const vDEP_CD = cmb_DEP_CD.getValue();
    const vEMP_NO = cmb_EMP_NO.getValue();
    let vAW_SCH_DD_END = cmb_AW_YYYY_END.getValue();
    const vExcnt = cmb_Excnt.getValue();
    const vAWARD_CD = cmb_Award.getValue(); // 표창유형

    // 시상년도 날짜체크
    if (!(await scwin.dateCheck(vAW_SCH_DD, vAW_SCH_DD_END))) {
        return;
    }
    scwin.gLdMktTp = rdo_MKT_ID.getValue();
    url += "&MKT_TP_CD=" + scwin.gLdMktTp;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&AW_SCH_DD=" + vAW_SCH_DD;
    url += "&AW_SCH_DD_END=" + vAW_SCH_DD_END;
    url += "&EXCNT=" + vExcnt;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&BELNG_DEP_CD=" + scwin.gBelngDepCd;
    url += "&AWARD_CD=" + vAWARD_CD;
    url += "&SCREN_ID=" + 'ULDSTF37301.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ByPass.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @param {*} strt_dd strt_dd
 * @param {*} end_dd end_dd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function(strt_dd, end_dd) {
    if (Number(strt_dd) > Number(end_dd)) {
        await $c.win.alert("시상년도 검색 시작년도가 종료년도보다 큽니다.");
        cmb_AW_YYYY.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(row, colid) {
    if (colid === "DEL" && row > 0) {
        const res = window.confirm("삭제하시겠습니까?");
        if (res) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            const vSELCT_BAS_YY = dts_List.getCellData(row, "SELCT_BAS_YY");
            let vISUR_CD = dts_List.getCellData(row, "ISUR_CD"); /*ORG SRC: dts_Delete.UserStatus(1) = TB_JOB_DELETE;*/ X = TB_JOB_DELETE;
            dts_Delete.setCellData(1, "SELCT_BAS_YY", vSELCT_BAS_YY);
            dts_Delete.setCellData(1, "ISUR_CD", vISUR_CD);
            trs_delete.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_delete",
                action : "/ByPass.do",
                ref : "dts_Delete",
                target : "trs_delete=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);

        // 시상년도 시작일
        let vAW_SCH_DD = cmb_AW_YYYY.getValue();
        // 시상년도 종료일
        let vAW_SCH_DD_END = cmb_AW_YYYY_END.getValue();
        if (scwin.gLdMktTp === "1" && (vAW_SCH_DD <= 2005 && 2005 <= vAW_SCH_DD_END)) {
            // 2016.03.07_시장구분이 1이고 조회기간에 2004년이 포함되고 시상년도가 2005또는 전체일때
            // 2016.04.11_조회기간 삭제에 따라 시장구분이 1이고 시상년도 시작년도, 종료년도에 2005년이 포함될때로 조건변경
            // 예외처리로 CJ 자산운용 추가_추후 아래와 같이 발행코드가 없는 법인은 추가 불가라는 답변을 박주환씨로부터 확인 받음.

            grd_Grid.Redraw = false;
            dts_List.insertRow();
            const nIdx = dts_List.getRowPosition();
            dts_List.setCellData(nIdx, "ISUR_CD", "-");
            dts_List.setCellData(nIdx, "COM_ABBRV", "CJ자산운용");
            dts_List.setCellData(nIdx, "SELCT_BAS_YY", "2004");
            dts_List.setCellData(nIdx, "EXCNT_DISCLS_CORP_AWARD_YY", "2005");
            dts_List.setCellData(nIdx, "EXCNT_DISCLS_CORP_TP_NM", "우수위원");
            dts_List.setCellData(nIdx, "LD_MKT_TP_CD", "1");
            $c.stf.fillGridHeaderTotalCnt(rowcount + 1, panel_page);
            dts_List.setRowPosition(0, 0);
            grd_Grid.Redraw = true;
        }
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    scwin.gDepCd = cmb_DEP_CD.getValue(); // ;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd === "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") === scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") === "") {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() === "") {
        txb_com_abbrv.setValue("");
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() === "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else return true;
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    await scwin.search();
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF37301.xml', SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "우수공시", type: "8"});
};

