/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid === "DEL") {
        await scwin.delete(row, colid);
    } else if (colid === "SELCT_BAS_YY" || colid === "EXCNT_DISCLS_CORP_AWARD_YY" || colid === "EXCNT_DISCLS_CORP_TP_NM") {
        // gCondStat = "U";

        // 발행기관코드
        scwin.gUIsurCd = dts_List.getCellData(row, "ISUR_CD");
        // 선정기준년도
        scwin.gSelctBasYy = dts_List.getCellData(row, "SELCT_BAS_YY");
        // 회사명
        scwin.gComAbbrv = dts_List.getCellData(row, "COM_ABBRV");
        // 유형
        scwin.gExcnt = dts_List.getCellData(row, "EXCNT_DISCLS_CORP_TP_CD");
        if (scwin.gLdMktTp !== "9") {
            // 밸류업지원부가 아닌경우 상세보기 불가
            if (dts_List.getCellData(row, "LD_MKT_TP_CD") === "9") {
                await $c.win.alert("밸류업 우수기업은 수정하실 수 없습니다.");
                return;
            }
        }
        if (scwin.gUIsurCd.length === 5) {
            params = "update";
            const options = {
                id: "ULDSTF37409",
                title: "우수공시법인 수정",
                type: "browserPopup",
                width: "580px",
                height: "330px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/dsclmgt/ULDSTF37409.gfm", options);
        }
    }
};

